    public GameBarrier(Lock lock) {
        this.mutex = lock;
        this.state = GAME_NOTREADY;
        this.cv = lock.newCondition();

        /* INITIALIZE ANY OTHER CLASS VARIABLES */
        this.numWaiters = 0;
        this.numPlayers = 0;
    }

    public void waitToPlay() {
        mutex.acquire();
        try {
            numWaiters++;
            while (state == GAME_FILLED || (state == GAME_NOTREADY && numWaiters < 4)) {
                cv.await();
            }

            if (state == GAME_NOTREADY && numWaiters >= 4) {
                state = GAME_FILLING;
                numWaiters -= 4;
                numPlayers = 4;
                cv.signalAll();
            }

            if (state == GAME_FILLING) {
                numPlayers--;
                if (numPlayers == 0) {
                    state = GAME_FILLED;
                }
            }
        } finally {
            mutex.release();
        }
    }

    public void donePlaying() {
        mutex.acquire();
        try {
            if (state == GAME_FILLED) {
                if (++numWaiters == 4) {
                    state = GAME_NOTREADY;
                    numWaiters = 0;
                    cv.signalAll();
                }
            }
        } finally {
            mutex.release();
        }
    }
