public class ConsoleBarrier {
    private static final int CONSOLE_WAIT = 0;
    private static final int CONSOLE_ALLOW = 1;

    private Lock mutex;
    private int state;
    private Condition cv;

    /* SPECIFY ANY OTHER CLASS VARIABLES */
    private int numPlayersAtConsole;

    public ConsoleBarrier(Lock lock) {
        this.mutex = lock;
        this.state = CONSOLE_WAIT;
        this.cv = lock.newCondition();

        /* INITIALIZE ANY OTHER CLASS VARIABLES */
        this.numPlayersAtConsole = 0;
    }

    public void waitAtConsole() {
        mutex.acquire();
        try {
            numPlayersAtConsole++;
            while (state == CONSOLE_WAIT) {
                cv.await();
            }

            if (numPlayersAtConsole == 4 && state == CONSOLE_ALLOW) {
                cv.signalAll();
            }
        } finally {
            mutex.release();
        }
    }

    public void playFinished() {
        mutex.acquire();
        try {
            numPlayersAtConsole--;
            if (numPlayersAtConsole == 0) {
                state = CONSOLE_WAIT;
            }
        } finally {
            mutex.release();
        }
    }

    public void allowAll() {
        mutex.acquire();
        try {
            state = CONSOLE_ALLOW;
            cv.signalAll();
        } finally {
            mutex.release();
        }
    }
}
